import{_ as e,c as l,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"地风升","description":"周易折中 - 地风升","frontmatter":{"title":"地风升","description":"周易折中 - 地风升"},"headers":[],"relativePath":"zh/classics/zhezhong/052.md","filePath":"zh/classics/zhezhong/052.md"}'),i={name:"zh/classics/zhezhong/052.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[h('<h1 id="地风升" tabindex="-1">地风升 <a class="header-anchor" href="#地风升" aria-label="Permalink to “地风升”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈升〉：“序卦萃者，聚也。聚而上者谓之升，故受之以《升》。物之积聚而益高大，聚而上也，故为《升》。所以次于《萃》也。为卦坤上巽下，木在地下，为地中生木，木生地中，长而益高，为《升》之象也。”</p><p>升：元亨，用见大人，勿恤，南征吉</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>升进而上也。卦自解来，柔上居四，内异外顺，九二刚中而五应之，是以其占如此。南征，前进也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>升者，进而上也。升进则有亨义，而以卦才之善，故元亨也。用此道以见大人，不假忧恤，前进则吉也。南征，前进也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>代氏渊曰 ：尊爻无此人，故不云“利见”。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>卦直言“元亨”而无他辞者，大有、鼎也。虽有他辞而非戒辞者，升也。历选易卦，惟此三者。盖大有与比相似，然所比者阴也、民也；所有者阳也、贤也。鼎与井相似，然往来井井者民也，大烹以养者贤也。升与渐相似，然渐者贤之有所需待而进者也，升者贤之无所阻碍而登者也。易道莫大于尚贤，而贤人得时之卦莫盛于此三者，故其彖皆曰“元亨”而无戒辞也。不曰“利见大人”而曰“用见”，代氏之说得之。</p><p>象曰：地中生木升，君子以顺德，积小以高大</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>（王肃本顺作愼，今案他书引此亦多作愼，意尤明白。盖古字通用也。说见上篇䊉卦。）</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>木生地中，长而上升，为升之象。君子观升之象，以顺脩其德，积累微小以至高大也。顺则可进，逆乃退也。万物之进皆以顺道也。善不积不足以成名，学业之充实，道德之崇高，皆由积累而至。积小所以成高大，升之义也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：木之生也，一日不长则枯；德之进也，一息不愼则退。必念念谨审，事事谨审，其德积小高大，当如木之升矣。</li></ul><p>彖曰：柔以时升</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦变释卦名。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：升之为义，自下升高，故就六五居尊以释名升之义。</p></li><li><p>徐氏几曰 ：升、晋二卦皆以柔为主，刚则有躁进之意。</p></li><li><p>龚氏焕曰 ：彖传“柔以时升”似指六五而言，非谓卦变。故下文言“刚中而应”，亦谓二应五也。</p></li></ul><p>巽而顺，刚中而应，是以大亨</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦德、卦体释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>以二体言，柔升谓坤上行也。巽既体卑而就下，坤乃顺时而上升。以时，谓时当升也。柔既上而成升，则下巽而上顺，以巽顺之道升，可谓时矣。二以刚中之道应于五，五以中顺之德应于二。能巽而顺，其升以时，是以元亨也。彖文误作大亨，解在大有卦。</p><p>用见大人，勿恤，有庆也；南征吉，志行也</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>凡升之道，必由大人。升于位，则由王公；升于道，则由圣贤。用巽顺刚中之道以见大人，必遂其升，勿恤（不忧其不遂也）。遂其升，则己之福庆而福庆及物也。南人之所向，南征谓前进也。前进则遂其升，而得行其志，是以吉也。</p><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>柔以时升之义，或主四言，或主五言，或主上体之坤而言。然卦之有六四、六五及坤居上体者多矣，皆得名为升乎？则其说似皆未确。盖时升者，固以坤居上体而四五得位言也。然惟巽为下体，故其升也有根。盖巽乃阴生之始也，阴自下生，以极于上，如木之自根而滋生，以至于枝叶繁盛，此谓升之义矣。此卦与无妄反对，无妄者阳为主于内也，而其究为健；升者阴为主于内也，而其究为顺。无妄之彖曰“刚自外来而为主于内”，明刚德自内以达于外也；升彖曰“柔以时升”，明阴道自下以达于上也。然则“柔以时升”云者，尤当以初六之义为重。故无妄六爻独初九曰吉，此卦六爻亦惟初六曰大吉。则二卦之所重者可知矣。其下云“巽而顺，刚中而应”，亦与无妄“动而健，刚中而应”之辞相似，皆连释名之义以释元亨也。</p><p>初六：允升，大吉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>初以柔顺居下，巽之主也。当升之时，巽于二阳，占者如之，则信能升而大吉矣。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初以柔居巽体之下，又巽之主，上承于九二之刚，巽之至者也。二以刚中之徳，上应于君，当升之任者也。允者，信从也。初之柔巽，唯信从于二，信二而从之，同升乃大吉也。二以徳言则刚中，以力言则当任。初之阴柔又无应援，不能自升，从于刚中之贤以进，是由刚中之道也。吉孰大焉。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰 ：以柔而升，升之义也。初以柔居下，即木之升言之，乃木之根，故信其升之必达而获大吉也。</p></li><li><p>何氏楷曰 ：初六巽主居下，犹木之根也，而得地气以滋之，其升也允矣。所以为升者巽也，所以为巽者初也。大吉孰如之？案此允升，允字当与晋之众允同义，盖不获上信友，不可以升进也。然晋三言众允，升初遂言允升，则王氏、何氏巽主木根之说是也。</p></li></ul><p>象曰：允升大吉，上合志也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>与在上者合志同升也。上谓九二，从二而升，乃与二同志也。能信从刚中之贤，所以大吉。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>吕氏大临曰：初六以柔居下，当升之时，柔进而上，虽处至下，志与三阴同升，众之所允，无所不利，故曰允升大吉。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>吕氏以上为上体三阴者是。</p><p>九二：孚乃利用禴，无咎</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>义见萃卦。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二阳刚而在下，五阴柔而居上。夫以刚而事柔，以阳而从阴，虽有时而然，非顺道也。以暗而临明，以刚而事弱，若黾勉于事势，非诚服也。上下之交不以诚，其可以久乎？其可以有为乎？五虽阴柔然居尊位，二虽刚阳事上者也。当内存至诚，不假文饰于外。诚积于中，则自不事外饰。故曰利用禴，谓尚诚敬也。自古刚强之臣事柔弱之君，未有不为矫饰者也。禴祭之简质者也，云孚乃谓既孚乃宜，不用文饰，专以其诚感通于上也。如是则得无咎。以刚强之臣而事柔弱之君，又当升之时，非诚意相交，其能免于咎乎？</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏清子曰 ：萃六二以中虚为孚，而与九五应；升九二以中实为孚，而与六五应。二爻虚实虽殊，其孚则一也。孚则虽用禴而亦利，故二爻皆曰“孚乃利用禴”。《彖》言“刚中而应”，指此爻也。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>升、晋之时，以柔为善。二刚而亦利者，以其中也。刚中有应，是见大人者也，故亦为升之利。初言吉，以君子得时之遇言也；二言无咎，以君子进身之道言也；六四则兼之。</p><p>象曰：九二之孚，有喜也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>二能以孚诚事上，则不唯为臣之道无咎而已，可以行刚中之道，泽及天下，是有喜也。凡象言有庆者，如是则有福庆及于物也；言有喜者，事既善而又有可喜也。如大畜童牛之梏元吉，象云有喜，盖梏于童则易，又免强制之难，是有可喜也。</p><p>九三：升虚邑</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>阳实阴虚，而坤有国邑之象。九三以阳刚当升时而进临于坤，故其象占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三以阳刚之才，正而且巽，上皆顺之，复有援应。以是而升，如入无人之邑，孰御哉？</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><p>案：诸爻皆有吉利之占，三独无之。则“升虚邑”者，但言其勇于进而无所疑畏耳。方升之时，故无凶咎之辞，然终不如二五之中、初四之顺也。九三过刚，与柔以时升之义反，故其辞非尽善。</p><p>象曰：升虚邑，无所疑也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>入无人之邑，其进无疑阻也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>苏氏轼曰：九三以阳用阳，其升也果矣，故曰升虚邑，无所疑也。不言吉者，其为祸福未可知也，存乎其人而已。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>干四曰“或之者疑之也”，故无咎。果于进而无所疑，可乎？苏氏之说善矣。</p><p>六四：王用亨于岐山，吉无咎</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>义见随卦。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四柔顺之才，上顺君之升，下顺下之进，已则止其所焉。以阴居柔，阴而在下，止其所也。昔者文王之居岐山之下，上顺天子而欲致之有道，下顺天下之贤而使之升进，已则柔顺谦恭，不出其位。至徳如此，周之王业用是而亨也。四能如是，则亨而吉且无咎矣。四之才固自善矣，复有无咎之辞何也？曰：四之才虽善，而其位当戒也。居近君之位，在升之时，不可复升，升则凶咎可知。故云如文王则吉而无咎也。然处大臣之位，不得无事于升，当上升其君之道，下升天下之贤，已则止其分焉。分虽当止，而徳则当升也，道则当亨也。尽斯道者，其唯文王乎？</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><p>案：卦义柔以时升，六四初交上体，又位在巽坤之闲，有南征之象，迫近尊位，有见大人之义，是爻之合于卦义者也。在己者用之以见大人则吉，为大人者用之以享神明则宜。与随上之义同，皆言“王用此人以享于山川”也。不曰“西山”而曰“岐山”，避《彖辞》“南征”之文。先儒或言岐山在周之西南。</p><p>象曰：王用亨于岐山，顺事也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以顺而升，登祭于山之象。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四居近君之位，而当升时，得吉而无咎者，以其有顺德也。以柔居坤，顺之至也。文王之亨于岐山，亦以顺时而已。上顺于上，下顺乎下，已顺处其义，故云顺事也。案：用贤以享于神明，是顺神明之心而事之者也。</p><p>六五：贞吉升阶</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阴居阳，当升而居尊位，必能正固，则可以得吉而升阶矣。阶，升之易者。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五以下有刚中之应，故能居尊位而吉。然质本阴柔，必守贞固乃得其吉也。若不能贞固，则信贤不笃，任贤不终，安能吉也？阶，所由而升也。任刚中之贤辅之而升，犹登进自阶，言有由而易也。指言九二正应，然在下之贤皆用升之阶也。能用贤，则彚升矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>李氏元量曰 ：贞吉升阶，升而有序，故以阶言之，谓宾主以揖逊而升者也。</p></li><li><p>王氏宗传曰 ：《彖传》言“柔以时升”，盖谓五也。</p></li><li><p>熊氏良辅曰 ：以顺而升，如历阶然。案：升至五而极，居坤地之中，亦有南征之象焉，乃卦之主也。不取君象，但为臣位之极者，与晋、渐之五同也。升阶须从李氏、熊氏之说，盖古者宾主三揖三让而后升阶，将上堂矣而犹退逊如此，以况君子始终之进以礼者也。升、晋之所以必贵于柔顺者，以此。升阶之戒不在贞字之外，乃发明贞吉之意尔。</p></li></ul><p>象曰：贞吉升阶，大得志也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>倚任贤才而能贞固，如是而升，可以致天下之大治，其志可大得也。君道之升，患无贤才之助尔，有助则犹自阶而升也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰：即彖所谓有庆志行者也。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>自初而升至此而升极矣，故初曰“上合志”，此曰“大得志”。</p><p>上六：冥升，利于不息之贞</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>以阴居升极，昏冥不已者也。占者遇此无适而利，但可反其不已于外之心，施之于不息之正而已。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>六以阴居升之极，昏冥于升，知进而不知止者也，其为不明甚矣。然求升不已之心，有时而用于贞正而当不息之事，则为宜矣。君子于贞正之徳，终日乾乾，自强不息。如上六不已之心用之于此，则利也。以小人贪求无已之心移于进徳，则何善如之？</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>石氏介曰 ：已在升极，是昧于升进之理。若能知时消息，但自消退不更求进，乃利也。</p></li><li><p>徐氏之祥曰 ：豫上乐极，故冥豫；升上进极，故冥升。案：冥升与晋其角之义同，皆进而不能退者也。以其刚也，故曰角；以其柔也，故曰冥。利于不息之贞，其戒亦与“维用伐邑”之义同，皆勤于自治，不敢以盛满自居者也。以其刚也，故曰伐邑；以其柔也，故曰不息之贞。</p></li></ul><p>象曰：冥升在上，消不富也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>昏冥于升极上而不知己，唯有消亡，岂复有加益也？不富，无复增益也。升既极，则有退而无进也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰：上六既不达存亡之几，以至于上位，固当消虚自损，不为尊大以自至于富盛也。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>胡氏之说善矣。然不曰“不息之贞，消不富也”，而曰“冥升在上”，者以在上明其位势之满盛，故当以自消损为贞也。</p>',114)])])}const m=e(i,[["render",n]]);export{b as __pageData,m as default};
